# region: render
def render(raw):
    return [len(tok.strip()) for tok in raw if tok.strip()]

# region: gather
def gather(xs, limit=9):
    return [v if v <= limit else limit for v in xs[1:]]

# region: intake
def intake(xs):
    return {'n': len(xs), 'total': sum(xs)}

# region: emit
def emit(summary, bar=3):
    out = dict(summary)
    out['grade'] = 'high' if summary.get('n', 0) >= bar else 'low'
    return out

# region: run
def run(raw):
    return emit(intake(gather(render(raw))))

